#ifndef CC_SELFHOST_H
#define CC_SELFHOST_H

#include <stddef.h>
#include <stdint.h>

/**
 * A qjsc-compiled module embedded in the self-hosted compiler binary.
 */
typedef struct {
    const char *name;
    const uint8_t *data;
    uint32_t size;
} EmbeddedModule;

/* Generated by scripts/selfhost.js from the qjsc output. */
extern EmbeddedModule cc_modules[];
extern const size_t cc_module_count;
void cc_init_modules(void);

#endif
